126	/**
127	 * Renders the 1–8 thread panes that live in the main content area. It bridges
128	 * the URL-follows-focus and external-navigation policies between the global
129	 * split-layout atom and the route, then recursively draws the layout tree.
130	 * A single pane renders identically to the pre-split page surface (no wrapper,
131	 * no focus ring); compact viewports disable splits entirely.
132	 */
133	interface SplitThreadAreaProps {
134	  routeContent?: PaneContent;
