142	/**
143	 * Browsers and virtualized timelines can normalize an invisible scroller back
144	 * to zero during the maximize layout transition. Record user-visible pane
145	 * scrollers as they move, ignore normalization events from hidden panes, and
146	 * restore the same mounted elements after each maximize/restore transition.
147	 */
148	function usePreservedSplitScrollPositions(maximizedPaneId: string | null) {
149	  const workspaceRef = useRef<HTMLDivElement>(null);
150	  const positionsRef = useRef(new Map<HTMLElement, PreservedScrollPosition>());
151	  const previousMaximizedPaneIdRef = useRef(maximizedPaneId);
152	
153	  const captureVisibleScrollPositions = useCallback(() => {
154	    const workspace = workspaceRef.current;
155	    if (workspace === null) {
156	      return;
157	    }
158	    for (const pane of workspace.querySelectorAll<HTMLElement>(
159	      `[${SPLIT_PANE_DATA_ATTR}]:not([aria-hidden="true"])`,
160	    )) {
161	      for (const element of pane.querySelectorAll<HTMLElement>("*")) {
162	        if (element.scrollLeft === 0 && element.scrollTop === 0) {
163	          positionsRef.current.delete(element);
164	          continue;
165	        }
166	        positionsRef.current.set(element, {
167	          left: element.scrollLeft,
168	          top: element.scrollTop,
169	        });
170	      }
171	    }
172	  }, []);
173	
174	  useLayoutEffect(() => {
175	    if (previousMaximizedPaneIdRef.current === maximizedPaneId) {
176	      return;
177	    }
178	    previousMaximizedPaneIdRef.current = maximizedPaneId;
179	
180	    const restore = () => {
181	      const workspace = workspaceRef.current;
182	      for (const [element, position] of positionsRef.current) {
183	        if (workspace === null || !workspace.contains(element)) {
184	          positionsRef.current.delete(element);
185	          continue;
186	        }
187	        element.scrollLeft = position.left;
188	        element.scrollTop = position.top;
189	      }
190	    };
191	
192	    // Restore before paint, then briefly across animation frames so passive
193	    // timeline effects, virtualization, and browser scroll anchoring cannot
194	    // overwrite the saved position while pane visibility settles.
195	    restore();
196	    let frame: number | null = null;
197	    let framesRemaining = 30;
198	    const restoreUntilSettled = () => {
199	      restore();
200	      framesRemaining -= 1;
201	      if (framesRemaining > 0) {
202	        frame = window.requestAnimationFrame(restoreUntilSettled);
203	      }
204	    };
205	    frame = window.requestAnimationFrame(restoreUntilSettled);
206	    return () => {
207	      if (frame !== null) {
208	        window.cancelAnimationFrame(frame);
209	      }
210	    };
211	  }, [maximizedPaneId]);
212	
213	  return { captureVisibleScrollPositions, workspaceRef };
214	}
