228	  const navigate = useNavigate();
229	  const store = useStore();
230	  const [storedLayout, setLayout] = useAtom(splitLayoutAtom);
231	  const [maximizedPaneId, setMaximizedPaneIdAtom] =
232	    useAtom(maximizedPaneIdAtom);
233	  const secondaryPanelRegistry = useMemo(
234	    () => createPaneSecondaryPanelRegistry(),
235	    [],
236	  );
237	
238	  const routeThread = useMemo<ThreadRoutePathArgs | null>(
239	    () => (projectId && threadId ? { projectId, threadId } : null),
240	    [projectId, threadId],
241	  );
242	  const currentContent = useMemo<PaneContent | null>(
243	    () => routeContent ?? (routeThread ? threadPaneContent(routeThread) : null),
244	    [routeContent, routeThread],
245	  );
246	
247	  // Fold external navigation (initial load, sidebar click, deep link) into the
248	  // layout. The reconcile is idempotent, so a URL that already matches the
249	  // focused pane is a no-op — no history spam, no render loop.
