251	    if (!threadSplitsEnabled || currentContent === null) {
252	      return;
253	    }
254	    setLayout((previous) =>
255	      reconcileLayoutForContent(previous, currentContent),
256	    );
257	  }, [currentContent, setLayout, threadSplitsEnabled]);
258	
259	  // Effective layout for render/handlers before the effect seeds the atom.
260	  const layout: SplitLayout | null =
261	    storedLayout ??
262	    (currentContent?.kind === "thread" && routeThread
263	      ? createSinglePaneLayout(routeThread)
