266	        : null);
267	  const panes = layout === null ? [] : listPanes(layout.root);
268	  const isSplitActive = splitWorkspaceActive && panes.length > 1;
269	  const maximizedPane =
270	    layout !== null && maximizedPaneId !== null
271	      ? findPane(layout.root, maximizedPaneId)
272	      : null;
273	  const effectiveMaximizedPaneId =
274	    layout !== null &&
275	    countPanes(layout.root) > 1 &&
276	    maximizedPaneId !== null &&
277	    maximizedPane !== null
