279	      : null;
280	  const {
281	    captureVisibleScrollPositions,
282	    workspaceRef: preservedScrollWorkspaceRef,
283	  } = usePreservedSplitScrollPositions(effectiveMaximizedPaneId);
284	  const setMaximizedPaneId = useCallback(
285	    (next: SetStateAction<string | null>) => {
286	      captureVisibleScrollPositions();
287	      setMaximizedPaneIdAtom(next);
288	    },
289	    [captureVisibleScrollPositions, setMaximizedPaneIdAtom],
290	  );
291	
