395	        }
396	      }
397	    },
398	    [layout, maximizedPaneId, navigate, setLayout, setMaximizedPaneId],
399	  );
400	
401	  const toggleMaximizePane = useCallback(
402	    (paneId: string) => {
403	      const current = store.get(splitLayoutAtom);
404	      const pane = current === null ? null : findPane(current.root, paneId);
405	      if (current === null || countPanes(current.root) < 2 || pane === null) {
406	        return;
407	      }
408	      if (current.focusedPaneId !== paneId) {
409	        const next = setFocus(current, paneId);
410	        store.set(splitLayoutAtom, next);
411	        const route = focusedPaneRoute(next);
