427	      );
428	      const edgePosition = (candidateId: string) => {
429	        const rect = rects.get(candidateId);
430	        if (rect === undefined) return 0;
431	        switch (side) {
432	          case "left":
433	            return rect.x;
434	          case "right":
435	            return -(rect.x + rect.w);
436	          case "top":
