647	            secondaryPanelRegistry={secondaryPanelRegistry}
648	            onFocusPane={focusPane}
649	            onClosePane={closePane}
650	            onToggleMaximizePane={toggleMaximizePane}
651	            onMovePaneToSide={movePaneToSide}
652	            onResize={resize}
