663	interface SplitPaneCommandHandlersProps {
664	  closePane: (paneId: string) => void;
665	  focusPane: (paneId: string) => void;
666	  isSplitActive: boolean;
667	  layout: SplitLayout;
668	  maximizedPaneId: string | null;
669	  panes: readonly PaneNode[];
