673	/** Mounted only while the experiment is enabled, so OFF unregisters commands. */
674	function SplitPaneCommandHandlers({
675	  closePane,
676	  focusPane,
677	  isSplitActive,
678	  layout,
679	  maximizedPaneId,
680	  panes,
681	  toggleMaximizePane,
682	}: SplitPaneCommandHandlersProps) {
683	  useAppCommandContext("splitActive", isSplitActive);
684	  useAppCommandHandler("pane.focus.previous", () => {
685	    if (!isSplitActive) return false;
686	    const paneId = getAdjacentPaneId(panes, layout.focusedPaneId, -1);
687	    if (paneId !== null) focusPane(paneId);
688	    return true;
689	  });
690	  useAppCommandHandler("pane.focus.next", () => {
691	    if (!isSplitActive) return false;
692	    const paneId = getAdjacentPaneId(panes, layout.focusedPaneId, 1);
693	    if (paneId !== null) focusPane(paneId);
694	    return true;
695	  });
696	  useIndexedAppCommandHandlers(PANE_FOCUS_APP_COMMAND_IDS, (index) => {
697	    if (!isSplitActive) return false;
698	    const paneId = getPaneIdAtReadingIndex(panes, index);
699	    if (paneId !== null) focusPane(paneId);
700	    return true;
701	  });
702	  useAppCommandHandler("pane.close", () => {
703	    if (!isSplitActive) return false;
704	    closePane(layout.focusedPaneId);
705	    return true;
706	  });
707	  useAppCommandHandler("pane.maximize.toggle", () => {
708	    if (!isSplitActive) return false;
709	    toggleMaximizePane(maximizedPaneId ?? layout.focusedPaneId);
710	    return true;
711	  });
712	  return null;
713	}
