1352	        "group relative z-[25] flex-shrink-0 transition-colors",
1353	        "bg-border-seam",
1354	        "hover:bg-ring/40 data-[dragging]:bg-ring/40",
1355	        hidden && "invisible pointer-events-none",
1356	        horizontal ? "w-px cursor-col-resize" : "h-px cursor-row-resize",
1357	      )}
1358	    >
1359	      <div
1360	        aria-hidden
1361	        data-split-divider-hit-target=""
1362	        onPointerDown={handlePointerDown}
1363	        className={cn(
1364	          "absolute z-10 touch-none bg-transparent",
1365	          horizontal
1366	            ? "-left-1.5 top-0 h-full w-3 cursor-col-resize"
1367	            : "left-0 -top-1.5 h-3 w-full cursor-row-resize",
1368	        )}
1369	      />
1370	    </div>
1371	  );
1372	}
1373	
1374	interface PaneStaleWatcherProps {
1375	  threadId: string;
1376	  onStale: () => void;
1377	}
1378	
1379	/**
1380	 * Watches a split pane's thread and signals when it becomes deleted (a 404 once
1381	 * the query settles) or archived, so the pane can be pruned. Shares the same
1382	 * react-query cache entry the pane's own view already subscribes to, so it adds
1383	 * a subscriber, not a fetch. Renders nothing.
1384	 */
1385	function PaneStaleWatcher({ threadId, onStale }: PaneStaleWatcherProps) {
1386	  const { data: thread, isSuccess, isError, error } = useThread(threadId);
1387	  // Archive optimistically stamps `archivedAt` before the server confirms, and a
1388	  // failed archive rolls it back — but the rollback can't restore a pane already
1389	  // pruned from the layout. So only treat "archived" as stale when no archive
1390	  // mutation is in flight (i.e. the archived state is server-settled). Delete,
1391	  // by contrast, drops the query and refetches, so its 404 / `deletedAt` are
1392	  // already server-confirmed and need no gate.
1393	  const archivesInFlight = useIsMutating({
1394	    predicate: (mutation) =>
1395	      mutation.options.meta?.lifecycleOperation === "archive_thread",
1396	  });
1397	  const isGone =
1398	    isError && error instanceof BbHttpError && error.status === 404;
1399	  const isDeleted =
1400	    isSuccess && thread !== undefined && thread.deletedAt !== null;
1401	  const isConfirmedArchived =
1402	    isSuccess &&
1403	    thread !== undefined &&
1404	    thread.archivedAt !== null &&
1405	    archivesInFlight === 0;
1406	  const isStale = isGone || isDeleted || isConfirmedArchived;
1407	
1408	  // Keep the latest callback without re-arming the fire effect: it fires once
1409	  // when staleness is first observed. Pruning unmounts this watcher (or is a
1410	  // no-op on the last pane), so a single fire is enough.
1411	  const onStaleRef = useRef(onStale);
1412	  useEffect(() => {
1413	    onStaleRef.current = onStale;
1414	  }, [onStale]);
1415	  useEffect(() => {
1416	    if (isStale) {
1417	      onStaleRef.current();
1418	    }
1419	  }, [isStale]);
1420	
1421	  return null;
1422	}
1423	
1424	function paneKey(node: LayoutNode): string {
1425	  return node.type === "pane"
1426	    ? node.paneId
1427	    : listPanes(node)
1428	        .map((pane) => pane.paneId)
1429	        .join("-");
1430	}
