318	// Tailwind utilities are not compiled in jsdom, so read the layer from the
319	// class token rather than from computed styles. `z-auto` and an absent z-index
320	// class both mean "paints in DOM order", which is layer 0 here.
321	function stackingLayer(element: HTMLElement): number {
322	  for (const token of element.classList) {
323	    const match = /^z-(?:\[(\d+)\]|(\d+))$/.exec(token);
324	    if (match !== null) {
325	      return Number(match[1] ?? match[2]);
326	    }
327	  }
328	  return 0;
329	}
