    const originalElementsFromPoint = document.elementsFromPoint;
    document.elementsFromPoint = vi.fn((x: number) =>
      x >= 500 ? [paneB] : [paneA],
    ) as typeof document.elementsFromPoint;
    Object.defineProperty(paneA, "getBoundingClientRect", {
      configurable: true,
      value: () => ({
