            type: "pane",
            paneId: "pane-2",
            content: { kind: "thread", threadId: "thr-a" },
          },
        ],
      });
      expect(paneA.className).toContain("invisible");
      expect(paneB.getAttribute("data-maximized")).toBe("true");
    } finally {
      document.elementsFromPoint = originalElementsFromPoint;
    }
  });

