    fireEvent.click(screen.getByTestId("maximize-thr-a"));
    const hiddenPane = screen
      .getByTestId("pane-thr-b")
      .closest("[data-split-pane-id]");
    await waitFor(() =>
      expect(hiddenPane?.getAttribute("aria-hidden")).toBe("true"),
