    fireEvent.click(screen.getByTestId("maximize-thr-a"));

    await waitFor(() => expect(hiddenScroller.scrollTop).toBe(12));
    expect(hiddenPane?.getAttribute("aria-hidden")).toBeNull();

    hiddenScroller.scrollTop = 0;
